pub const WMI_MAX_EHTCAP_RATE_SET: c_int = 3;
// Used for EHT MCS-NSS array. Data at each array index follows the format given
// in IEEE P802.11be/D2.0, May 20229.4.2.313.4.
//
// Index interpretation:
// 0 - 20 MHz only sta, all 4 bytes valid
// 1 - index for bandwidths <= 80 MHz except 20 MHz-only, first 3 bytes valid
// 2 - index for 160 MHz, first 3 bytes valid
// 3 - index for 320 MHz, first 3 bytes valid
//
pub const WMI_MAX_EHT_SUPP_MCS_2GHZ_SIZE: c_int = 2;
pub const WMI_MAX_EHT_SUPP_MCS_5GHZ_SIZE: c_int = 4;
pub const WMI_EHTCAP_TXRX_MCS_NSS_IDX_80: c_int = 0;
pub const WMI_EHTCAP_TXRX_MCS_NSS_IDX_160: c_int = 1;
pub const WMI_EHTCAP_TXRX_MCS_NSS_IDX_320: c_int = 2;

